/* Wavetable view and table picker for the oscillator cards.
 *
 * Previews come from assets/wave-previews/NN.bin (generated by gen.py):
 * 64 waves x 64 samples per table, offset-binary bytes (128 = zero).  The
 * terrain stacks every wave of the table back to front, draws the selected
 * position as stepped 8-bit samples in the layer colour, and shades the
 * positions the Wave env and velocity can reach.  Dragging across it sets the
 * position.  With Link on, Osc 2 shows Osc 1's table and position, as the DSP
 * plays them.
 */
import { formatValue } from "./format.js";
import { waveReach, waveSpan } from "./curves.js";
import { sourceColor } from "./mod.js";

const tables = new Map();
const loads = new Map();

export function loadTable(index) {
  if (tables.has(index)) return Promise.resolve(tables.get(index));
  if (!loads.has(index)) {
    const url = "assets/wave-previews/" + String(index).padStart(2, "0") + ".bin";
    loads.set(index, fetch(url, { cache: "force-cache" })
      .then((r) => { if (!r.ok) throw new Error(url + " " + r.status); return r.arrayBuffer(); })
      .then((buf) => {
        const data = new Uint8Array(buf);
        if (data.length !== 64 * 64) throw new Error(url + " has " + data.length + " bytes");
        tables.set(index, data);
        return data;
      })
      .catch((err) => { console.error("wave preview", err); loads.delete(index); return null; }));
  }
  return loads.get(index);
}

function el(tag, cls, text) {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (text !== undefined) e.textContent = text;
  return e;
}

export function cssVar(name) {
  return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
}

/** Keep a canvas's backing store at its CSS size times the pixel ratio. */
export function sizeCanvas(canvas) {
  const dpr = window.devicePixelRatio || 1;
  const w = Math.max(1, Math.round(canvas.clientWidth * dpr));
  const h = Math.max(1, Math.round(canvas.clientHeight * dpr));
  if (canvas.width !== w || canvas.height !== h) { canvas.width = w; canvas.height = h; }
  return { ctx: canvas.getContext("2d"), w, h, dpr };
}

/** Draw one 64-sample wave as 8-bit steps into the box (x, y, w, h). */
export function stepPath(ctx, samples, x, y, w, h) {
  const n = samples.length;
  ctx.beginPath();
  for (let i = 0; i < n; i++) {
    const yy = y + h - (samples[i] / 255) * h;
    const x0 = x + (i / n) * w, x1 = x + ((i + 1) / n) * w;
    if (i === 0) ctx.moveTo(x0, yy); else ctx.lineTo(x0, yy);
    ctx.lineTo(x1, yy);
  }
}

function linePath(ctx, samples, x, y, w, h) {
  const n = samples.length;
  ctx.beginPath();
  for (let i = 0; i < n; i++) {
    const xx = x + (i / (n - 1)) * w;
    const yy = y + h - (samples[i] / 255) * h;
    if (i === 0) ctx.moveTo(xx, yy); else ctx.lineTo(xx, yy);
  }
}

/** Run fn once per frame at most. */
function frameThrottle(fn) {
  let queued = false;
  return () => {
    if (queued) return;
    queued = true;
    requestAnimationFrame(() => { queued = false; fn(); });
  };
}

/**
 * The terrain for oscillator n.  Returns { el, positionBinding } where the
 * element contains the canvas and a caption.
 */
export function waveView(store, n) {
  const p = "osc" + n + "_";
  const wrap = el("div", "wave-view");
  const canvas = el("canvas", "wave-canvas");
  canvas.tabIndex = -1;
  canvas.setAttribute("role", "img");
  const caption = el("div", "wave-caption");
  const pos = el("span", "wave-pos");
  const reach = el("span", "wave-reach");
  caption.append(pos, reach);
  wrap.append(canvas, caption);

  const linked = () => n === 2 && store.value("osc2_link") >= 0.5;
  const src = (bare) => linked() ? bare.replace("osc2_", "osc1_") : bare;
  const state = () => ({
    table: Math.round(store.value(src(p + "table"))),
    wave: Math.round(store.value(src(p + "wave"))),
    wenv: store.value(src(p + "wenv")),
    vel: store.value(src(p + "vel")),
  });

  /* Sources other than Wave env and velocity that move this oscillator's
   * wave, as { name, color, span } in the order voice.c adds them: matrix
   * slots aimed at the wave (Osc 1's while Link holds Osc 2 to it), then
   * Aftertouch to Wave. */
  const otherSources = () => {
    const meta = store.meta;
    const dst = meta.modTargetKeys.indexOf("osc" + (linked() ? 1 : n) + "_wave");
    const names = meta.params.m1_src.options;
    const parts = [];
    for (const sl of store.mod?.slots ?? []) {
      if (sl.src <= 0 || sl.amt === 0 || sl.dst !== dst) continue;
      parts.push({ name: names[sl.src], color: sourceColor(meta, sl.src),
        span: waveSpan(sl.amt, !!(meta.modSources[sl.src] || {}).bipolar) });
    }
    const at = store.value("at_wave");
    if (at !== 0) {
      parts.push({ name: "Chan AT", color: sourceColor(meta, names.indexOf("Chan AT")), span: waveSpan(at, false) });
    }
    return parts;
  };
  const slot = (x) => Math.min(60, Math.max(0, x));
  const widthOf = (span) => span[1] - span[0];

  const draw = () => {
    const s = state();
    const meta = store.metaFor(p + "wave");
    const others = otherSources();
    const r = waveReach(s.wave, s.wenv, s.vel, others.map((o) => o.span));
    const base = Math.round(s.wave);
    pos.textContent = (linked() ? "Linked · " : "") + "Wave " + formatValue(meta, s.wave);
    const label = r.fixed ? "fixed classic wave" : r.hi - r.lo >= 1
      ? "reach " + Math.round(r.lo) + "–" + Math.round(r.hi) : "";
    const chips = r.fixed ? [] : others.filter((o) => widthOf(o.span) >= 1).map((o) => {
      const chip = el("span", "wave-reach-src", o.name + " " + Math.round(slot(base + o.span[0])) + "–"
        + Math.round(slot(base + o.span[1])));
      chip.style.color = o.color;
      return chip;
    });
    reach.replaceChildren(label, ...chips);
    canvas.setAttribute("aria-label", "Osc " + n + " wavetable, wave " + s.wave);
    const data = tables.get(s.table);
    const { ctx, w, h, dpr } = sizeCanvas(canvas);
    ctx.clearRect(0, 0, w, h);
    if (!data) { loadTable(s.table).then((d) => d && schedule()); return; }
    const color = cssVar("--l" + store.layer);
    const dim = cssVar("--line-2");
    // Each reaching source is drawn in its own colour; Wave env and velocity
    // keep the layer colour.
    const owners = [{ color, span: waveSpan(s.wenv, false) }, { color, span: waveSpan(s.vel, false) }, ...others]
      .filter((o) => widthOf(o.span) >= 1)
      .map((o) => ({ color: o.color, lo: Math.floor(slot(base + o.span[0])), hi: Math.ceil(slot(base + o.span[1])) }));
    // Waterfall: wave 0 at the front-left, 63 at the back-right.
    const depthX = w * 0.22, depthY = h * 0.42;
    const waveW = w - depthX - 8 * dpr, waveH = h - depthY - 10 * dpr;
    const ox = (i) => 4 * dpr + depthX * (i / 63);
    const oy = (i) => 4 * dpr + depthY * (1 - i / 63);
    ctx.lineJoin = "round";
    for (let i = 63; i >= 0; i--) {
      if (i === s.wave) continue;
      const inReach = !r.fixed && i >= Math.floor(r.lo) && i <= Math.ceil(r.hi) && r.hi - r.lo >= 1;
      const owner = inReach && owners.find((o) => i >= o.lo && i <= o.hi);
      ctx.globalAlpha = inReach ? 0.55 : (i >= 61 ? 0.35 : 0.22 + 0.25 * (1 - i / 63));
      ctx.strokeStyle = inReach ? (owner ? owner.color : color) : dim;
      ctx.lineWidth = dpr;
      linePath(ctx, data.subarray(i * 64, i * 64 + 64), ox(i), oy(i), waveW, waveH);
      ctx.stroke();
    }
    // Selected wave: stepped, with a soft fill to the centre line.
    const sel = data.subarray(s.wave * 64, s.wave * 64 + 64);
    const x0 = ox(s.wave), y0 = oy(s.wave);
    ctx.globalAlpha = 0.16;
    ctx.fillStyle = color;
    stepPath(ctx, sel, x0, y0, waveW, waveH);
    ctx.lineTo(x0 + waveW, y0 + waveH / 2);
    ctx.lineTo(x0, y0 + waveH / 2);
    ctx.closePath();
    ctx.fill();
    ctx.globalAlpha = 1;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2 * dpr;
    stepPath(ctx, sel, x0, y0, waveW, waveH);
    ctx.stroke();
  };
  const schedule = frameThrottle(draw);

  for (const k of ["table", "wave", "wenv", "vel"]) {
    store.bind("osc1_" + k, schedule);
    if (n === 2) store.bind("osc2_" + k, schedule);
  }
  if (n === 2) store.bind("osc2_link", (v) => { wrap.classList.toggle("linked", Number(v) >= 0.5); schedule(); });
  store.bind("at_wave", schedule);
  store.mod?.onSlots(schedule); // the matrix re-reads its slots on every change to them
  store.bind("edit_layer", schedule);
  new ResizeObserver(schedule).observe(canvas);

  /* Drag across the terrain to pick a position (classic slots included). */
  const position = store.bind(p + "wave", () => {});
  let dragging = false;
  const pick = (e) => {
    if (linked()) return;
    const rect = canvas.getBoundingClientRect();
    const f = Math.min(1, Math.max(0, (e.clientX - rect.left) / rect.width));
    const v = String(Math.round(f * 63));
    if (v !== store.get(position.key)) position.set(v);
  };
  canvas.addEventListener("pointerdown", (e) => {
    if (e.button !== 0 || linked()) return;
    dragging = true;
    canvas.setPointerCapture(e.pointerId);
    wrap.classList.add("active");
    pick(e);
  });
  canvas.addEventListener("pointermove", (e) => { if (dragging) pick(e); });
  const end = () => { dragging = false; wrap.classList.remove("active"); };
  canvas.addEventListener("pointerup", end);
  canvas.addEventListener("pointercancel", end);
  return wrap;
}

/* ------------------------------------------------------------ table picker */

function drawThumb(canvas, data) {
  const { ctx, w, h, dpr } = sizeCanvas(canvas);
  ctx.clearRect(0, 0, w, h);
  const dim = cssVar("--dim");
  const accent = cssVar("--text");
  // Three positions overlaid show how the table morphs.
  [[0, dim, 0.45], [30, dim, 0.7], [60, accent, 1]].forEach(([i, c, a]) => {
    ctx.globalAlpha = a;
    ctx.strokeStyle = c;
    ctx.lineWidth = (i === 60 ? 1.6 : 1) * dpr;
    linePath(ctx, data.subarray(i * 64, i * 64 + 64), 3 * dpr, 4 * dpr, w - 6 * dpr, h - 8 * dpr);
    ctx.stroke();
  });
  ctx.globalAlpha = 1;
}

/**
 * The table selector: a button showing the current table that opens a
 * searchable grid of every table with a morph thumbnail.
 */
export function tablePicker(store, n) {
  const bare = "osc" + n + "_table";
  const meta = store.metaFor(bare);
  const wrap = el("div", "table-picker");
  const label = el("div", "choice-label", "Table");
  const button = el("button", "table-btn");
  button.type = "button";
  button.setAttribute("aria-haspopup", "dialog");
  const name = el("span", "table-name");
  const num = el("span", "table-num");
  button.append(num, name);
  wrap.append(label, button);

  const pop = el("div", "table-pop");
  pop.hidden = true;
  pop.setAttribute("role", "dialog");
  pop.setAttribute("aria-label", "Osc " + n + " wavetable");
  const search = el("input", "search");
  search.type = "search";
  search.placeholder = "Search " + meta.options.length + " tables";
  const grid = el("div", "table-grid");
  pop.append(search, grid);
  wrap.appendChild(pop);

  const paint = (i) => {
    name.textContent = meta.options[i] || "?";
    num.textContent = String(i).padStart(2, "0");
    button.title = meta.name + ": " + (meta.options[i] || "");
    for (const b of grid.children) b.classList.toggle("on", Number(b.dataset.index) === i);
  };
  const binding = store.bind(bare, (v) => paint(Math.round(Number(v) || 0)));
  store.bind("osc2_link", (v) => {
    if (n === 2) wrap.classList.toggle("inactive", Number(v) >= 0.5);
  });

  const cells = meta.options.map((opt, i) => {
    const b = el("button", "table-cell");
    b.type = "button";
    b.dataset.index = String(i);
    const c = el("canvas", "table-thumb");
    b.append(c, el("span", "", String(i).padStart(2, "0") + " " + opt));
    b.onclick = () => { binding.set(String(i)); paint(i); close(); button.focus(); };
    grid.appendChild(b);
    return { b, c, name: opt.toLowerCase(), drawn: false };
  });

  const open = () => {
    pop.hidden = false;
    search.value = "";
    filter();
    const current = Math.round(Number(store.get(binding.key)) || 0);
    cells.forEach((cell, i) => cell.b.classList.toggle("on", i === current));
    cells.forEach((cell, i) => loadTable(i).then((d) => {
      if (d && !pop.hidden) { drawThumb(cell.c, d); cell.drawn = true; }
    }));
    search.focus();
    cells[current]?.b.scrollIntoView({ block: "nearest" });
  };
  const close = () => { pop.hidden = true; };
  const filter = () => {
    const q = search.value.trim().toLowerCase();
    cells.forEach((cell, i) => { cell.b.hidden = !!q && !cell.name.includes(q) && String(i) !== q; });
  };
  search.oninput = filter;
  button.onclick = () => (pop.hidden ? open() : close());
  pop.addEventListener("keydown", (e) => {
    if (e.key === "Escape") { close(); button.focus(); }
    if (e.key === "Enter" && e.target === search) {
      e.preventDefault(); // focus moves to the button; Enter must not re-open
      const first = cells.find((c) => !c.b.hidden);
      if (first) first.b.click();
    }
  });
  document.addEventListener("pointerdown", (e) => { if (!wrap.contains(e.target)) close(); });
  return wrap;
}
